// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Sosyoloji temel kavramları ve toplumsal kurumlar (zor).
const ozSocialscience1Zor = <(String, String, List<String>, String)>[
  ('Bir sosyolog, aynı mahallede oturan iki ailenin harcama alışkanlıklarını karşılaştırırken kendi beğenilerini değerlendirmeye katmamaya özen gösteriyor. Sosyologun bu tutumu en çok hangi ilkeyle ilgilidir?', 'Değerden bağımsızlık', ['Tümevarımsal genelleme', 'Kültürel yayılma', 'Toplumsal hareketlilik'], 'Weber\'in vurguladığı değerden bağımsızlık ilkesi, araştırmacının kişisel değer yargılarını bulgulara karıştırmamasını ister.'),
  ('"Sosyoloji, toplumsal olaylarda doğa bilimlerindeki kadar kesin yasalara ulaşamaz." Bu yargının en güçlü gerekçesi hangisidir?', 'İnsan davranışının bilinçli, değişken ve çok etkenli olması', ['Sosyologların gözlem yapmaktan kaçınması', 'Toplumsal olayların hiçbir biçimde ve hiçbir yerde tekrarlanmaması', 'Sosyolojide istatistik kullanılmaması'], 'Toplumsal olaylarda insanlar bilinçli seçimler yapar ve çok sayıda etken bir arada bulunur; bu da kesin, evrensel yasalar kurmayı zorlaştırır.'),
  ('19. yüzyılda toplumsal olayları açıklamaya yönelik olarak doğa bilimlerindeki başarının toplum incelemesine taşınması isteği, sosyolojinin hangi yönelimle doğmasına yol açmıştır?', 'Pozitivizm', ['Romantizm', 'Skolastisizm', 'Mistisizm'], 'Doğa bilimlerinin gözlem ve deneye dayalı başarısı, toplumun da benzer yöntemlerle incelenebileceği düşüncesini doğurmuş; bu yönelim pozitivizm adını almıştır.'),
  ('Comte\'un bilimler sıralamasında sosyolojiyi en sona, en karmaşık bilim olarak koymasının gerekçesi hangisidir?', 'Toplumsal olguların öteki bilimlerin konularını da içeren en karmaşık olgular olması', ['Sosyolojinin en eski bilim olması', 'Sosyolojinin matematik kullanmaması', 'Sosyolojinin yalnız tarihle ilgilenmesi'], 'Comte bilimleri genelden özele, basitten karmaşığa sıralar; toplum, fiziksel ve biyolojik koşulları da kapsadığından sosyoloji en karmaşık bilimdir.'),
  ('Durkheim\'ın din sosyolojisindeki görüşüne göre dinsel ritüellerin temel toplumsal işlevi hangisidir?', 'Topluluğun ortak bilincini ve dayanışmasını güçlendirmek', ['Ekonomik eşitsizliği gizlemek', 'Bireyin kişisel yeteneklerini ve yaratıcılığını geliştirmek', 'Siyasal iktidarı devirmek'], 'Durkheim Dinsel Yaşamın İlkel Biçimleri adlı eserinde ritüellerin topluluğu bir araya getirerek kolektif bilinci pekiştirdiğini savunur.'),
  ('Durkheim\'a göre suçun belirli ölçülerde her toplumda bulunması "normal" sayılabilir. Bu görüşün dayanağı hangisidir?', 'Suça verilen tepkinin ortak değerleri hatırlatıp pekiştirmesi', ['Suçun toplumsal düzeni hiçbir şekilde etkilememesi', 'Suçun yalnızca ekonomik yoksunluktan doğması', 'Suçluların topluma yararlı olması gerektiği düşüncesi'], 'Durkheim\'a göre suça karşı ortak tepki, toplumun neyi kabul edip neyi reddettiğini görünür kılar ve ortak değerleri güçlendirir.'),
  ('Weber\'in modern dünyada büyüsel ve dinsel açıklamaların gerilemesini anlatmak için kullandığı kavram hangisidir?', 'Dünyanın büyüsünün bozulması', ['Kültürel gecikme', 'Toplumsal hareketlilik ve göç', 'Sınıf bilinci'], 'Weber\'e göre rasyonelleşmeyle birlikte dünya gizemli güçlerle açıklanmaktan çıkar; bunu "dünyanın büyüsünün bozulması" olarak adlandırır.'),
  ('Weber\'in bürokratik rasyonelliğin bireyi kuşatmasını anlatan benzetmesi hangisidir?', 'Demir kafes', ['Görünmez el', 'Ayna benlik', 'Küresel köy'], 'Weber, aşırı rasyonelleşmiş ve bürokratikleşmiş modern düzenin bireyi kuralların içine hapsetmesini "demir kafes" benzetmesiyle anlatır.'),
  ('Weber ile Marx\'ın kapitalizmin doğuşuna ilişkin yaklaşımları karşılaştırıldığında Weber\'in ayırıcı vurgusu hangisidir?', 'Dinsel düşünce ve değerlerin ekonomik yapıyı etkileyebilmesi', ['Üretim araçlarının mülkiyetinin tek belirleyici olması', 'Kapitalizmin devrimle hemen sona ereceği', 'Ekonominin toplumun hiçbir alanını etkilemediği'], 'Marx ekonomik altyapıyı belirleyici görürken Weber, Protestan ahlakı örneğinde olduğu gibi fikirlerin ve değerlerin de ekonomik değişmeyi etkileyebildiğini savunur.'),
  ('İşçilerin, kendi çıkarlarına aykırı olan düzeni doğal ve haklı saymaları Marx\'ın hangi kavramıyla açıklanır?', 'Yanlış bilinç', ['Anomi', 'Kültürel görecelik', 'Organik dayanışma'], 'Yanlış bilinç, ezilen sınıfın egemen sınıfın ideolojisini benimseyerek kendi gerçek çıkarlarını göremedikleri durumdur.'),
  ('Marx\'ın toplumsal değişmeyi açıklayışı ile Comte\'un yaklaşımı karşılaştırıldığında Marx\'ın temel vurgusu hangisidir?', 'Değişmenin itici gücünün sınıf çatışması ve ekonomik çelişkiler olması', ['Değişmenin insan düşüncesinin aşamalarıyla olması', 'Toplumun hiç değişmeyen bir denge içinde olması', 'Değişmenin yalnız coğrafi koşullardan kaynaklanması'], 'Comte değişmeyi düşüncenin üç hal aşamasıyla açıklarken Marx, tarihin itici gücünü üretim ilişkilerindeki çelişkiler ve sınıf mücadelesi olarak görür.'),
  ('İbn Haldun\'a göre bir hanedanın kentli yaşama geçtikten sonra zayıflayıp yıkılmasının temel nedeni hangisidir?', 'Lüks ve rahatlıkla asabiyetin zamanla çözülmesi', ['Nüfusun aşırı azalarak toprakların tamamen boşalması', 'Komşu devletlerin hiç saldırmaması', 'Bilimin ve sanatın gelişmemesi'], 'İbn Haldun\'a göre hadari yaşamın getirdiği bolluk ve rahatlık dayanışma duygusunu zayıflatır; asabiyet çözülünce devlet çöker.'),
  ('İbn Haldun\'un devletlerin yaklaşık üç kuşak içinde doğup yaşlanıp çöktüğünü öne sürmesi onun hangi yaklaşımını yansıtır?', 'Toplumsal olayları belirli düzenliliklere bağlayan döngüsel tarih anlayışını', ['Toplumsal olayları yalnız ilahi iradeyle açıklamayı', 'Toplumun sürekli düz bir çizgide ilerlediği inancını', 'Toplumsal değişmeyi tümüyle reddetmeyi'], 'İbn Haldun devletlerin yükselişini ve çöküşünü tekrarlanan bir döngü içinde ele alır; bu, olaylarda nedensel düzenlilik arayan bir yaklaşımdır.'),
  ('Prens Sabahattin\'in toplum sınıflamasına göre Osmanlı toplumunun geri kalmasının temel nedeni hangisidir?', 'Toplumun cemaatçi yapıda olması ve bireysel girişimin gelişmemesi', ['Toplumun aşırı sanayileşmiş olması', 'Merkezi yönetimin çok zayıf olması', 'Nüfusun tamamen kentlerde yaşaması'], 'Prens Sabahattin, cemaatçi toplumlarda bireyin aileye ve devlete bağımlı olduğunu, bu yüzden girişimciliğin gelişmediğini savunmuştur.'),
  ('Ziya Gökalp\'in toplum anlayışını biçimlendiren batılı sosyolog kimdir ve bu etki en açık hangi yönde görülür?', 'Durkheim; toplumu bireyden üstün ve ortak bilinçle bütünleşmiş bir varlık sayması', ['Marx; tarihi sınıf mücadelesiyle açıklaması', 'Weber; bireysel eylemin anlamına öncelik vermesi', 'Spencer; toplumu bireylerin basit toplamı sayması'], 'Gökalp, Durkheim\'ın toplumu bireyleri aşan ahlaki bir bütün olarak gören anlayışını benimsemiş, millî kültür kavramını bu temelde geliştirmiştir.'),
  ('Bir araştırmacının gözlem yaptığı grubun, gözlendiğini fark edince davranışlarını değiştirmesi hangi sorunu doğurur?', 'Verilerin doğal davranışı yansıtmaması', ['Örneklemin aşırı büyük olması', 'Araştırmanın nicel hale gelmesi', 'Hipotezin kesin olarak doğrulanması'], 'Gözlenen kişilerin davranışlarını değiştirmesi, toplanan verilerin gerçek durumu yansıtmamasına yol açar; bu durum araştırmanın geçerliğini düşürür.'),
  ('İşlevselciliğe yöneltilen "toplumsal değişmeyi ve çatışmayı açıklamakta zorlanır" eleştirisinin dayanağı hangisidir?', 'Kuramın denge ve uzlaşmayı toplumun olağan durumu sayması', ['Kuramın yalnız bireysel davranışı incelemesi', 'Kuramın ekonomiyi tek belirleyici görmesi', 'Kuramın toplumsal kurumları dikkate almaması'], 'İşlevselcilik toplumu dengeye yönelen bir sistem olarak görür; bu yüzden çatışma ve köklü değişmeleri açıklamada yetersiz kaldığı ileri sürülür.'),
  ('Durkheim\'a göre mekanik dayanışmanın egemen olduğu toplumlarda hukukun baskın niteliği hangisidir?', 'Cezalandırıcı (baskıcı) hukuk', ['Onarıcı (iade edici) hukuk düzeni', 'Uluslararası hukuk', 'Ticaret hukuku'], 'Mekanik dayanışmada suç kolektif bilince saldırı sayılır ve sert cezalarla karşılanır; organik dayanışmada ise zararın giderilmesini amaçlayan onarıcı hukuk öne çıkar.'),
  ('Durkheim\'a göre toplumlar mekanik dayanışmadan organik dayanışmaya geçerken kolektif bilinçte ne olur?', 'Zayıflar ve bireysellik alanı genişler', ['Daha da güçlenerek bireyi tamamen kuşatır', 'Hiç değişmeden aynı kalır', 'Yalnızca dinsel alanda ortadan kalkar'], 'İşbölümü arttıkça bireyler farklılaşır, ortak bilincin kapsamı daralır ve bireysel farklılıklara daha çok yer açılır.'),
  ('Bir köyde yaşlıların danışılan kişiler olması, kadın ve erkek işlerinin ayrılması ve aile reisinin kararları belirlemesi bir arada düşünüldüğünde, bu durum en iyi hangi kavramla nitelenir?', 'Köyün toplumsal yapısı', ['Köyün kültürel gecikmesi', 'Köyün nüfus hareketliliği', 'Köyün sapma davranışları'], 'Yaş, cinsiyet ve aile içi konumlara bağlı düzenli ilişkiler bütünü, köyün toplumsal yapısını oluşturur.'),
  ('Doktora derecesine sahip bir kişinin geçimini düşük ücretli ve güvencesiz bir işten sağlaması sosyolojide hangi kavramla açıklanır?', 'Statü tutarsızlığı', ['Kazanılmış statü ve konum', 'Rol kümesi', 'Dikey hareketlilik'], 'Statü tutarsızlığı, bireyin eğitim, gelir ve meslek gibi boyutlardaki konumlarının birbiriyle uyuşmadığı durumdur.'),
  ('Bir sosyolog, "Kazanılmış statü de tümüyle bireyin çabasına bağlı değildir." diyor. Bu görüşü en iyi destekleyen gözlem hangisidir?', 'Aile geliri yüksek çocukların nitelikli eğitime daha kolay erişmesi', ['Bazı statülerin doğuştan elde edilmesi', 'Statülerin rol kümesi oluşturması', 'Her kişinin birden çok statüsü olması'], 'Kazanılmış statüler çaba gerektirse de bu çabanın olanakları ailenin ekonomik ve kültürel durumundan etkilenir.'),
  ('Bir okulun öğrencilerinin rakip okulla yapılan maç sırasında kendi okullarına daha çok bağlandıklarını hissetmeleri neyi gösterir?', 'Dış grupla karşıtlığın iç grup dayanışmasını güçlendirebileceğini', ['Birincil grupların her zaman dağıldığını', 'Toplumsal kategorilerin etkileşim içermediğini', 'Referans gruplarının bireyi etkilemediğini'], 'Dış grupla rekabet ya da karşıtlık, iç gruptaki "biz" duygusunu ve dayanışmayı pekiştirebilir.'),
  ('Bir fabrikada resmi örgüt şemasında yer almayan, ama öğle yemeklerini birlikte yiyen işçilerin kendi aralarında oluşturduğu arkadaş grubunun önemi en iyi hangisiyle açıklanır?', 'Resmi olmayan grupların iş ortamındaki tutum ve davranışları etkileyebilmesi', ['Resmi grupların hiçbir işlevinin olmaması', 'İşçilerin yalnızca yazılı kurallara göre davranması', 'Arkadaş gruplarının ikincil grup sayılması'], 'Hawthorne araştırmaları gibi çalışmalar, resmi olmayan işyeri gruplarının üretkenlik ve iş doyumunu önemli ölçüde etkilediğini göstermiştir.'),
  ('Gustave Le Bon\'un kalabalık psikolojisi üzerine görüşüne göre kalabalığa katılan bireylerde en belirgin değişim hangisidir?', 'Bireysel sorumluluk duygusunun azalıp davranışların duygusal hale gelmesi', ['Bireylerin daha akılcı ve temkinli davranması', 'Bireylerin grupla hiç etkileşim kurmaması', 'Bireylerin yazılı kurallara daha sıkı uyması'], 'Le Bon, kalabalık içindeki bireyin anonimleşerek etkiye açık hale geldiğini ve bireysel olarak yapmayacağı davranışlara yönelebildiğini savunmuştur.'),
  ('Bir konser bitiminde dağılmakta olan seyircilerin bir yangın alarmı üzerine panikle çıkışa koşması, kalabalık türleri açısından nasıl değerlendirilir?', 'Rastlantısal kalabalığın etkin (eylemci) kalabalığa dönüşmesi', ['Toplumsal kategorinin birincil gruba dönüşmesi', 'Kitlenin resmi örgüte dönüşmesi', 'Toplumsal kurumun ortaya çıkması'], 'Geçici olarak bir arada bulunan insanlar ortak bir uyarıcıyla aniden aynı yönde harekete geçtiğinde etkin bir kalabalık ortaya çıkar.'),
  ('Simmel\'e göre çatışmanın toplumsal yaşamda olumlu bir işlevi olabilir. Bu görüşü en iyi açıklayan durum hangisidir?', 'Dış bir tehdide karşı yaşanan çatışmanın grup içi bütünleşmeyi artırması', ['Çatışmanın her durumda grubu dağıtması', 'Çatışmanın yalnız bireyler arasında görülmesi', 'Çatışmanın kurallar ve normlar yaratmaması'], 'Simmel ve onu izleyen Coser, çatışmanın grup sınırlarını belirginleştirdiğini ve grup içi dayanışmayı güçlendirebildiğini vurgulamıştır.'),
  ('Bir yöneticinin çalışanlar arasındaki rekabeti aşırı artıran bir ödül sistemi kurması, uzun vadede hangi riski doğurabilir?', 'Rekabetin çatışmaya dönüşerek işbirliğini zayıflatması', ['Çalışanların tümünün aynı statüye ve aynı ücrete sahip olması', 'Kurumun tamamen asimile olması', 'Çalışanlar arasında hiçbir etkileşim kalmaması'], 'Kuralların aşındığı ya da kaybetmenin çok ağır sonuçlar doğurduğu yoğun rekabet, rakibi engellemeye yönelik çatışmaya dönüşebilir.'),
  ('Bir toplumda "bireysel başarı" değerinin öne çıkması ile "aileye bağlılık" değerinin zayıflaması aynı dönemde görülüyorsa bu durum en çok neyle ilişkilendirilebilir?', 'Toplumsal değişme sürecinde değer hiyerarşisinin dönüşmesi', ['Değerlerin hiçbir zaman değişmemesi', 'Normların değerlerden bağımsız biçimde ortaya çıkması', 'Toplumsal kurumların tamamen ortadan kalkması'], 'Değerler zaman içinde öncelik sırası açısından değişebilir; kentleşme ve sanayileşme gibi süreçler bireyciliği güçlendirebilir.'),
  ('"Değerler toplumsal bütünleşmenin temelidir." yargısını en iyi destekleyen gerekçe hangisidir?', 'Ortak değerlerin bireylerin davranışlarına ortak bir yön vererek birlik sağlaması', ['Değerlerin her bireyde farklı olması', 'Değerlerin yalnızca yasalarla korunması', 'Değerlerin sürekli çatışmaya yol açması'], 'Ortak değerler bireylere ortak hedefler ve ölçütler sağlar; böylece toplumun üyeleri arasında bağ kurulur.'),
  ('Bir toplumda yaygın olarak uyulan bir görgü kuralının zamanla yazılı bir yasaya dönüştürülmesi en çok neyi gösterir?', 'Normların değişen ihtiyaçlarla resmileşebileceğini', ['Görgü kurallarının hiçbir zaman ve hiçbir koşulda değişmediğini', 'Yasaların toplumsal değerlerden bağımsız olduğunu', 'Normların yalnız bireysel olduğunu'], 'Toplum için önem kazanan bazı yazısız kurallar zamanla yazılı ve devlet yaptırımına bağlı hukuk kurallarına dönüşebilir.'),
  ('"Kahve ikram edilirken önce yaşlılara verilir" kuralı hangi açıdan bir norm, hangi açıdan bir değer ile ilişkilidir?', 'Ne yapılacağını söylediği için norm, yaşlılara saygıya dayandığı için değerle ilişkilidir', ['Yazılı olduğu için değer, yaptırımı olmadığı için normdur', 'Yalnız yaşlılara uygulandığı için kategoridir', 'Hiçbir yaptırımı olmadığı için yalnız bir alışkanlıktır'], 'Davranışın nasıl yapılacağını belirleyen kural bir normdur; bu kuralın dayandığı ilke olan yaşlılara saygı ise bir değerdir.'),
  ('Toplumsal kontrolün en etkili biçiminin "içselleştirilmiş kontrol" olduğu söylenir. Bunun nedeni hangisidir?', 'Bireyin normlara dış baskı olmadan kendi isteğiyle uyması', ['Polis gücünün her yerde bulunması', 'Cezaların ağırlaştırılması', 'Bireylerin kamerayla ve polisle sürekli gözetim altında tutulması'], 'Toplumsallaşmayla içselleştirilen normlara birey, cezalandırılma korkusu olmadan kendiliğinden uyar; bu dış denetimden daha süreklidir.'),
  ('Michel Foucault\'nun Bentham\'ın tasarımından yararlanarak modern toplumdaki gözetim düzenini anlatmak için kullandığı kavram hangisidir?', 'Panoptikon', ['Demir kafes', 'Habitus', 'Anomi'], 'Panoptikon, gözetlenenlerin her an izlenip izlenmediklerini bilmedikleri hapishane tasarımıdır; Foucault bunu bireylerin kendilerini denetlemeye başladığı modern disiplin toplumunun simgesi olarak kullanır.'),
  ('Bir mahallede gençlerin suç oranı yüksekse, sosyolojik açıdan en sağlıklı açıklama yaklaşımı hangisidir?', 'İşsizlik, eğitim olanakları ve akran ilişkileri gibi toplumsal etkenleri birlikte incelemek', ['Suçu yalnızca gençlerin kişisel kötülüğüne bağlamak', 'Mahalledeki yüksek suç oranını tesadüf saymak', 'Suçun nedenini yalnız iklim koşullarında aramak'], 'Sosyoloji sapmayı tek bir bireysel nedene indirgemez; toplumsal çevre, fırsat yapısı ve öğrenme süreçlerini birlikte inceler.'),
  ('"Kültür bireyi biçimlendirir, ama birey de kültürü değiştirir." yargısını en iyi örnekleyen durum hangisidir?', 'Bir mucidin geliştirdiği aracın zamanla herkesin günlük yaşamına girmesi', ['Bireylerin kültürü hiç sorgulamadan sürdürmesi', 'Kültürün yalnız devlet tarafından belirlenmesi', 'Bireyin kültürden bağımsız olarak yetişmesi'], 'Bireyler kültürü toplumsallaşmayla edinir; ama yenilik yapan bireyler de kültüre yeni öğeler katarak onu dönüştürür.'),
  ('Bir göçmenin yeni ülkesinde dili, kuralları ve yaşam tarzını bilmemesi nedeniyle yaşadığı şaşkınlık ve uyum güçlüğü hangi kavramla adlandırılır?', 'Kültür şoku', ['Kültürel gecikme', 'Karşıt kültür', 'Kültürel yayılma'], 'Kültür şoku, bireyin alışık olmadığı bir kültürle karşılaştığında yaşadığı yönelim bozukluğu ve uyum sorunudur.'),
  ('Bir toplumun dışarıdan gelen bir yeniliği olduğu gibi değil, kendi değerlerine uyarlayarak benimsemesi neyi gösterir?', 'Kültürel öğelerin yayılırken yeniden yorumlanabildiğini', ['Kültürel yayılmanın hiç gerçekleşmediğini', 'Kültürün dış etkilere tamamen kapalı olduğunu', 'Toplumun kendi kültürünü tamamen yitirdiğini'], 'Toplumlar dışarıdan aldıkları öğeleri çoğunlukla kendi kültürel kalıplarına uydurarak benimser; yayılma seçici bir süreçtir.'),
  ('Ilımlı düzeydeki bir etnosentrizmin grup açısından olumlu sayılabilecek bir işlevi hangisidir?', 'Grup içinde aidiyet ve dayanışma duygusunu güçlendirmesi', ['Diğer kültürleri daha iyi anlamayı sağlaması', 'Kültürel önyargıları tamamen ortadan kaldırması', 'Kültürler arası iletişimi kolaylaştırması'], 'Kendi kültürüne bağlılık grup bütünleşmesini destekleyebilir; ancak aşırı etnosentrizm önyargı ve çatışmaya yol açar.'),
  ('Kültürel göreceliğin aşırı uçta yorumlanmasına yöneltilen en önemli eleştiri hangisidir?', 'Evrensel insan haklarını ihlal eden uygulamaların da eleştirilememesine yol açabilmesi', ['Kültürlerin birbirini hiç etkilememesi', 'Bütün kültürlerin tek tipleşmesine neden olması', 'Etnosentrizmi zorunlu hale getirmesi'], 'Her uygulamayı yalnızca kendi bağlamında meşru saymak, insan onuruna aykırı uygulamaları da eleştirilmez kılabilir; bu aşırı göreceliğin temel sorunudur.'),
  ('Aynı ailede büyüyen iki kardeşin farklı arkadaş çevreleri ve okullar nedeniyle farklı değerler edinmesi neyi gösterir?', 'Toplumsallaşmanın birden çok ajansla gerçekleştiğini', ['Ailenin toplumsallaşmada hiçbir rolünün olmadığını ve çocuğu etkilemediğini', 'Toplumsallaşmanın yalnız kalıtımla belirlendiğini', 'Kardeşlerin farklı kültürlere doğduğunu'], 'Aile ortak olsa da akran grubu, okul ve medya gibi farklı ajanslar bireylerin toplumsallaşmasını farklılaştırabilir.'),
  ('Mead\'in benlik gelişiminde çocuğun annesi, öğretmeni ya da polis gibi tek tek kişilerin rollerini taklit ederek oynadığı aşamaya ne ad verilir?', 'Taklit oyunu (play) aşaması', ['Organize oyun aşaması', 'Genelleştirilmiş öteki aşaması', 'Kurumsallaşma aşaması'], 'Mead\'e göre çocuk önce önemli ötekilerin rollerini tek tek taklit eder (play); daha sonra kurallı oyunlarda grubun bütün rollerini hesaba katar (game).'),
  ('Davis ve Moore\'un işlevselci tabakalaşma kuramına göre toplumsal eşitsizliğin varlık nedeni hangisidir?', 'Önemli ve zor görevlere yetenekli kişileri çekmek', ['Egemen sınıfın sömürüyü sürdürme isteği ve çıkarları', 'Dinsel inançların insanları doğuştan ayırması', 'Coğrafi koşulların insanları farklılaştırması'], 'Davis ve Moore\'a göre toplum, önemli ve uzun eğitim gerektiren işleri daha yüksek ödüllerle cazip kılar; eşitsizlik bu işlevi görür.'),
  ('Bir ülkede ekonominin tarımdan hizmet sektörüne kayması nedeniyle çok sayıda kişinin daha yüksek statülü işlere geçmesine ne ad verilir?', 'Yapısal hareketlilik', ['Bireysel hareketlilik ve kişisel çaba', 'Yatay hareketlilik', 'Aşağı doğru hareketlilik'], 'Yapısal hareketlilik, bireysel çabadan çok ekonomik ve teknolojik değişmelerin meslek yapısını dönüştürmesinden kaynaklanan hareketliliktir.'),
  ('Bir toplumda toplumsal hareketliliği en çok artırabilecek uygulama hangisidir?', 'Herkese nitelikli eğitime eşit erişim sağlanması', ['Mesleklerin babadan oğula zorunlu olarak geçmesi', 'Evliliğin yalnızca aynı tabaka içinde yapılması', 'Belirli işlerin doğuştan belirlenmiş gruplara ayrılması'], 'Eğitime eşit erişim, bireylerin doğdukları konumdan bağımsız olarak yeteneklerine göre yükselebilmesinin en önemli yoludur.'),
  ('Yüksek eğitimli uzmanların daha iyi koşullar için başka ülkelere gitmesi, gönderen ülke açısından en çok hangi sonucu doğurur?', 'Nitelikli insan gücünün kaybı', ['Ülkenin nüfusunun hızla artması', 'Ülkede işsizliğin tamamen ortadan kalkması', 'Kentleşmenin durması'], 'Beyin göçü, gönderen ülkenin eğitimine yatırım yaptığı nitelikli insan kaynağını yitirmesine yol açar.'),
  ('Sosyolojide "kurum" ile "örgüt" kavramlarının ayrılmasının önemi en iyi hangi seçenekte açıklanmıştır?', 'Kurumun soyut kural ve ilişki örüntüsünü, örgütün ise bu örüntünün somut birimlerini anlatması', ['Kurumun yalnızca devlete bağlı birimleri, örgütün özel şirketleri anlatması', 'Kurum ile örgütün aynı anlama gelmesi', 'Örgütün her zaman kurumdan daha geniş kapsamlı olması'], 'Örneğin eğitim bir kurumdur; okullar ise bu kurumun somut örgütleridir. Bu ayrım soyut yapı ile somut birimleri karıştırmamayı sağlar.'),
  ('Bir toplumda ailenin üstlendiği eğitim ve sağlık bakımı gibi işlevlerin zamanla okul ve hastane gibi kurumlara geçmesi sosyolojide hangi süreçle açıklanır?', 'Kurumsal farklılaşma ve işlev aktarımı', ['Kültürel gecikme ve teknolojik geri kalma', 'Toplumsal kategorinin oluşması', 'Asimilasyon ve kültürel erime'], 'Modernleşmeyle birlikte toplumsal işlevler uzmanlaşmış kurumlara dağılır; böylece aile bazı geleneksel işlevlerini başka kurumlara aktarır.'),
  ('Modern toplumlarda ailenin eğitim, sağlık ve üretim işlevlerinin bir kısmını başka kurumlara bırakması ailenin önemini yitirdiği anlamına gelir mi?', 'Hayır; duygusal destek ve toplumsallaştırma gibi işlevler önemini korur', ['Evet; aile tüm işlevlerini yitirmiştir ve artık hiçbir rolü kalmamıştır', 'Evet; aile yalnızca ekonomik bir birim olarak kalmıştır', 'Hayır; aile bütün işlevlerini eskisi gibi tek başına sürdürmektedir'], 'Aile bazı işlevlerini aktarmış olsa da sevgi, güven, duygusal destek ve erken toplumsallaşma işlevleri hâlâ ailede yoğunlaşır.'),
  ('Kan bağı ya da evlilik ilişkisi olmadan, sünnet töreni gibi bir vesileyle kurulan ve kuşaklar boyu süren "kirvelik" bağı sosyolojide nasıl nitelendirilir?', 'Manevi (yapay) akrabalık', ['Kan akrabalığı ve soy bağı', 'Hısımlık ve evlilik bağı', 'Toplumsal kategori ve sınıf bağı'], 'Kirvelik, kan ve evlilik dışında törensel bir bağla kurulan, akrabalık gibi hak ve yükümlülükler doğuran manevi akrabalıktır.'),
  ('Kentleşmeyle birlikte geniş aile çözülse de akrabalar arasında yardımlaşma ve sık görüşmenin sürmesini anlatan "değiştirilmiş geniş aile" kavramı neyi vurgular?', 'Ayrı yaşasalar da akrabalık bağlarının işlevini sürdürebildiğini', ['Akrabalık ilişkilerinin kentlerde tamamen sona erdiğini', 'Bütün ailelerin yeniden aynı evde yaşamaya başladığını', 'Çekirdek ailenin hiçbir zaman ortaya çıkmadığını'], 'Eugene Litwak gibi sosyologlar, ayrı hanelerde yaşayan akrabaların da birbirine destek olmaya devam ettiğini göstermiştir.'),
  ('Bourdieu\'ye göre okul sisteminin toplumsal eşitsizliği yeniden üretmesinin temel nedeni hangisidir?', 'Okulun egemen sınıfın kültürel sermayesini ölçüt alması', ['Okullarda hiçbir sınav yapılmaması', 'Bütün öğrencilerin aynı aileden gelmesi', 'Okulların yalnızca kırsal bölgelerde bulunması ve kentlerde hiç olmaması'], 'Okulun ödüllendirdiği dil, beğeni ve bilgi biçimleri üst sınıf ailelerde zaten edinilmiştir; bu nedenle bu çocuklar okulda avantajlı başlar.'),
  ('Öğretmenlerin bazı öğrencilerden yüksek başarı beklemesinin o öğrencilerin başarısını gerçekten artırmasını anlatan sosyolojik kavram hangisidir?', 'Kendini doğrulayan kehanet', ['Kültürel gecikme ve geride kalma', 'Örtük işlev', 'Rol gerilimi'], 'Merton\'un tanımladığı kendini doğrulayan kehanet, başlangıçta yanlış olabilen bir beklentinin davranışları değiştirerek kendini gerçekleştirmesidir; Rosenthal-Jacobson araştırması bunu okulda göstermiştir.'),
  ('Ekonomik kurumdaki değişmelerin aile kurumunu etkilemesine en uygun örnek hangisidir?', 'Kadınların ücretli işe girmesiyle ev içi işbölümünün yeniden düzenlenmesi', ['Bir ailenin hafta sonu piknik yerini değiştirmesi', 'Yeni doğan bebeğe ad verilmesi', 'Bayramda akrabaların ziyaret edilmesi'], 'Kadınların ücretli çalışmaya katılması, ev işleri ve çocuk bakımının eşler arasında paylaşımını değiştirerek aile yapısını etkiler.'),
  ('Weber\'e göre karizmatik otoritenin lider öldükten sonra kurallara ve örgütlere dönüşerek kalıcılaşmasına ne ad verilir?', 'Karizmanın rutinleşmesi', ['Dünyanın büyüsünün bozulması', 'Demir kafes', 'Kültürel gecikme'], 'Karizma doğası gereği geçicidir; liderden sonra hareketin sürmesi için otorite geleneksel ya da yasal-ussal biçimlere dönüşür. Weber buna karizmanın rutinleşmesi der.'),
  ('Siyaset sosyolojisinin siyaset bilimine göre ayırıcı ilgi alanı en iyi hangisidir?', 'Siyasal davranışların toplumsal sınıf, eğitim ve kültür gibi toplumsal temelleri', ['Anayasa maddelerinin teknik hukuki yorumu', 'Devletlerin askeri stratejilerinin hesaplanması', 'Seçim sandıklarının fiziksel tasarımı'], 'Siyaset sosyolojisi iktidar, katılım ve siyasal tutumların toplumsal yapıyla ilişkisini inceler; örneğin oy verme davranışının eğitim ve sınıfla ilişkisi.'),
  ('Bürokrasinin modern toplumlarda yaygınlaşmasının Weber\'e göre temel nedeni hangisidir?', 'Büyük ölçekli işleri hesaplanabilir ve verimli yürütebilmesi', ['Yöneticilerin kişisel çıkarlarını gizleyebilmesi', 'Geleneksel otoriteyi güçlendirmesi', 'İşlemleri yavaşlatıp kararları ertelemesi'], 'Weber bürokrasiyi teknik olarak en verimli örgütlenme biçimi sayar; büyük nüfuslu modern toplumların yönetimi bu tür örgütlenmeyi zorunlu kılar.'),
  ('İnternete erişim olanakları ve dijital becerilerdeki eşitsizlikler sonucunda toplum kesimleri arasında oluşan farka ne ad verilir?', 'Dijital uçurum', ['Kültürel görecelik', 'Örtük program', 'Toplumsal kategori'], 'Dijital uçurum, gelir, yaş, eğitim ve bölge gibi etkenlere bağlı olarak bilgi teknolojilerine erişimde ortaya çıkan eşitsizliktir.'),
  ('Bilimin bir toplumsal kurum olarak ele alınmasında sosyolojinin ilgilendiği konuya örnek hangisidir?', 'Bilimsel bilginin üretiminde finansman ve kurumların etkisi', ['Bir kimyasal tepkimenin denklemini denkleştirmek', 'Bir gezegenin kütlesini hesaplamak', 'Bir bitkinin genetik yapısını belirlemek'], 'Bilim sosyolojisi bilimsel etkinliğin toplumsal örgütlenmesini, kurumları, normları ve topluma etkilerini inceler.'),
  ('Bir ülkede doğurganlık oranının uzun süre düşük kalması ve ortalama yaşam süresinin uzaması hangi toplumsal sonucu doğurur?', 'Nüfusun yaşlanması', ['Genç nüfusun hızla artması', 'Bebek ölüm hızının yükselmesi', 'Kırsal nüfusun hızla çoğalması'], 'Az doğum ve uzun yaşam, nüfus içinde yaşlıların payını artırarak nüfusun yaşlanmasına yol açar; bu da emeklilik ve bakım sistemlerini etkiler.'),
  ('Bir ülkede çalışma çağındaki nüfusun bağımlı nüfusa (çocuklar ve yaşlılar) göre oransal olarak en yüksek olduğu döneme ne ad verilir?', 'Demografik fırsat penceresi', ['Kültürel gecikme dönemi ve uyumsuzluk', 'Malthusçu tuzak', 'Nüfus patlaması'], 'Demografik fırsat penceresi, üretken yaştaki nüfusun yoğun olduğu ve uygun politikalarla ekonomik büyümenin hızlanabileceği dönemdir.'),
  ('Bir ailenin temel ihtiyaçlarını karşılayabildiği halde toplumun genel yaşam düzeyinin çok altında kalması hangi kavramla açıklanır?', 'Göreli yoksulluk', ['Mutlak yoksulluk', 'Anomi ya da kuralsızlık', 'Kültürel gecikme'], 'Göreli yoksulluk, bireyin içinde yaşadığı toplumun ortalama yaşam standardına göre yoksun kalmasıdır; bu nedenle ölçütü toplumdan topluma değişir.'),
  ('Bir kentte hızla artan suç oranlarıyla mücadelede yalnızca cezaları ağırlaştırmanın yeterli olmayacağı görüşünün sosyolojik gerekçesi hangisidir?', 'Suçun yoksulluk, eğitim ve dışlanma gibi toplumsal nedenleri olması', ['Cezaların toplum üzerinde hiçbir etkisinin bulunmaması', 'Suçun yalnızca kalıtımla geçmesi', 'Suçun hiçbir zaman önlenememesi'], 'Sosyoloji suçu besleyen toplumsal koşullara dikkat çeker; kalıcı çözüm için bu nedenlerin de ele alınması gerekir.'),
  ('Bazı grupların eğitim, sağlık, istihdam ve toplumsal katılım gibi alanlardan sistematik olarak uzak kalmasını anlatan kavram hangisidir?', 'Toplumsal dışlanma', ['Toplumsal hareketlilik', 'Kültürel yayılma', 'Organik dayanışma'], 'Toplumsal dışlanma, yalnızca gelir eksikliğini değil, toplumsal yaşamın birçok alanına katılamamayı anlatan çok boyutlu bir kavramdır.'),
  ('Antropoloji ile sosyolojinin tarihsel olarak inceleme alanları arasındaki geleneksel ayrım hangisidir?', 'Antropolojinin daha çok küçük ölçekli toplumlara, sosyolojinin modern toplumlara yönelmesi', ['Antropolojinin yalnız hayvanları, sosyolojinin yalnız insanları incelemesi', 'Sosyolojinin yalnız biyolojik özelliklere bakması', 'Antropolojinin hiç alan araştırması yapmaması'], 'Antropoloji uzun süre Batı dışındaki küçük ölçekli toplumları, sosyoloji ise sanayileşmiş modern toplumları incelemiştir; bugün bu ayrım belirginliğini yitirmiştir.'),
  ('Norbert Elias\'ın "Uygarlık Süreci" adlı eserinde sofra adabı ve beden denetimi gibi davranışların tarihsel değişimini incelemesinin temel sonucu hangisidir?', 'Dış denetimin zamanla öz denetime dönüştüğü', ['Toplumların hiçbir zaman davranış kurallarını değiştirmediği', 'Görgü kurallarının doğuştan geldiği', 'Davranış kurallarının yalnızca yasalarla belirlendiği'], 'Elias, devletleşme ve karşılıklı bağımlılığın artmasıyla bireylerin duygu ve davranışlarını giderek daha çok kendi kendine denetlemeye başladığını göstermiştir.'),
  ('W. I. Thomas\'ın "İnsanlar bir durumu gerçek olarak tanımlarlarsa, o durum sonuçları bakımından gerçek olur" sözü sosyolojiye hangi düşünceyi kazandırmıştır?', 'Durumların öznel tanımının davranışları belirlediği', ['Toplumsal olguların bireyden tamamen bağımsız olduğu', 'Yalnızca ölçülebilir olguların incelenebileceği', 'İnsan davranışının yalnızca kalıtımla açıklanabileceği'], 'Thomas teoremi, insanların bir durumu nasıl algıladıklarının, o durumun gerçek sonuçlarını belirlediğini vurgular; kendini doğrulayan kehanet kavramına da temel olmuştur.'),
  ('Geleneksel Türk köyünde muhtar, ihtiyar heyeti, imam ve köyün yaşlılarının sorunların çözümünde birlikte etkili olması toplumsal kontrol açısından neyi gösterir?', 'Resmi ve resmi olmayan denetimin bir arada işlediğini', ['Köyde hiçbir toplumsal kontrolün bulunmadığını', 'Yalnızca yazılı yasaların uygulandığını', 'Toplumsal kontrolün tamamen kente ve kentli kurumlara bırakıldığını'], 'Muhtar ve ihtiyar heyeti resmi yetkiye sahipken yaşlılar ve imam geleneksel saygınlıklarıyla resmi olmayan denetimde etkilidir.'),
  ('Bir araştırmacının yalnızca kendisine kolay ulaşılabilen arkadaşlarına anket uygulayıp sonucu bütün ülkeye genellemesinin temel sorunu hangisidir?', 'Örneklemin evreni temsil etmemesi', ['Anketin nitel bir teknik olması', 'Hipotezin hiç kurulmamış olması', 'Verilerin çok fazla sayıda ve karmaşık olması'], 'Rastgele seçilmeyen ve evrenin özelliklerini yansıtmayan bir örneklemden elde edilen sonuçlar genellenemez.'),
  ('Bir kurumu inceleyen iki sosyologdan biri onun toplumsal dengeyi sağladığını, diğeri ise belirli grupların çıkarına işlediğini ileri sürüyor. Bu durum sosyoloji açısından en doğru nasıl değerlendirilir?', 'Farklı kuramlar aynı olguyu farklı yönleriyle açıklayabilir', ['Sosyologlardan birinin mutlaka bilimsel yöntemi bırakmış olması', 'Kurumların incelenmesi bilimsel olarak olanaksızdır', 'Sosyolojide yalnızca tek bir kuram geçerlidir'], 'İşlevselcilik ve çatışma kuramı gibi farklı yaklaşımlar aynı olgunun farklı boyutlarını aydınlatır; sosyoloji çok kuramlı bir bilimdir.'),
  ('Bir gazeteci ile bir sosyologun aynı mahalledeki göçmenleri ele alışı karşılaştırıldığında sosyologun ayırıcı özelliği hangisi olmalıdır?', 'Sistemli veri toplama ve bulguları kuramla ilişkilendirme', ['Olayları en çarpıcı yönüyle hemen haberleştirme', 'Yalnızca tek bir kişinin öyküsünü anlatma', 'Kişisel yargılarını öne çıkarma'], 'Sosyolog sistematik yöntemlerle veri toplar, bulgularını kuramsal çerçevelerle yorumlar ve genellenebilir sonuçlara ulaşmaya çalışır.'),
  ('Çekirdek ailede yaşlıların bakımının giderek huzurevi ve bakım hizmetleri gibi kurumlara geçmesi hangi toplumsal dönüşümle en çok ilişkilidir?', 'Kentleşme ve kadınların çalışma yaşamına katılması', ['Tarım toplumuna geri dönülmesi ve köylerin büyümesi', 'Geniş ailenin yeniden yaygınlaşması', 'Doğum oranlarının çok yükselmesi'], 'Kentte küçük konutlar ve ücretli çalışan aile üyeleri, geleneksel olarak ailede üstlenilen bakım işlevinin kurumlara aktarılmasına yol açar.'),
  ('"Aile kurumu her toplumda vardır, ama biçimi toplumdan topluma değişir." Bu yargıyı en iyi destekleyen gözlem hangisidir?', 'Bazı toplumlarda geniş, bazılarında çekirdek ailenin yaygın olması', ['Her toplumda ailelerin tam olarak aynı sayıda üyeden oluşması', 'Bazı toplumlarda hiç evlilik kuralı bulunmaması', 'Ailenin yalnızca sanayi toplumlarında görülmesi'], 'Aile evrensel bir kurumdur; ancak büyüklüğü, otorite yapısı ve evlilik kuralları kültüre göre farklılaşır.'),
  ('Bir grubun üyelerini "biz" duygusuyla birbirine bağlayan unsurlardan biri olarak "grup normları"nın önemi nedir?', 'Üyelerden beklenen davranışları belirleyerek grubu düzenlemesi', ['Grubun hiçbir kurala bağlı olmamasını sağlaması', 'Üyelerin grubu terk etmesini kolaylaştırması', 'Grubun bütünüyle bir kalabalığa dönüşmesi'], 'Grup normları üyelerin nasıl davranacağını belirler; bu ortak kurallar grubun sürekliliğini ve kimliğini destekler.'),
  ('Bir köyde kadınların uzun yıllar sürdürdüğü el dokumacılığının, fabrika üretimi ucuz kumaşların gelmesiyle ortadan kalkması hangi değerlendirmeye uygundur?', 'Teknolojik değişme geleneksel üretim biçimlerini dönüştürebilir', ['Kültür dış etkilere karşı tamamen dirençlidir', 'Manevi kültür maddi kültürü her zaman belirler', 'Kültürel değişme yalnız kentlerde görülür'], 'Yeni üretim teknolojileri ve pazar koşulları geleneksel zanaatları ortadan kaldırarak ekonomik ve kültürel yaşamı değiştirebilir.'),
  ('Bir çocuğun ailede "büyüklere saygı" değerini öğrenmesi, okulda ise "herkese eşit davranma" ilkesini öğrenmesi arasındaki farkı en iyi açıklayan hangisidir?', 'Farklı ajansların farklı değer ve normları öne çıkarabilmesi', ['Ailenin toplumsallaşmada hiçbir rolünün olmaması', 'Okulun yalnızca bilgi aktarması, değer öğretmemesi', 'Toplumsallaşmanın yalnız çocuklukta gerçekleşmesi'], 'Toplumsallaşma ajansları farklı değerleri vurgulayabilir; birey bunları zaman içinde bir araya getirir ya da aralarında seçim yapar.'),
  ('Kırdan kente göç eden birinci kuşak ile kentte doğan ikinci kuşağın değerleri arasında farklar görülmesi hangi süreçle açıklanabilir?', 'Kentte gerçekleşen toplumsallaşmanın yeni kuşağı farklı biçimlendirmesi', ['Göçmenlerin kentte hiçbir şey öğrenmemesi', 'Değerlerin yalnızca kalıtımla geçmesi', 'Kentli kültürün köy kültürüyle tamamen aynı olması'], 'Kentte doğan kuşak okul, akran ve medya aracılığıyla kentli değerleri daha yoğun edinir; bu kuşaklar arası farklılaşmaya yol açar.'),
  ('"Orta sınıfın genişlemesi toplumsal istikrara katkı yapar." görüşünü en iyi destekleyen gerekçe hangisidir?', 'Uç kutuplar arasındaki gerilimi yumuşatan geniş bir ara kesim oluşturması', ['Toplumdaki bütün bireylerin aynı gelire sahip olması', 'Orta sınıfın hiçbir siyasal görüşünün bulunmaması', 'Toplumsal hareketliliği tümüyle durdurması'], 'Geniş bir orta kesim, çok zengin ile çok yoksul arasındaki keskin ayrışmayı azaltarak çatışma olasılığını düşürebilir.'),
  ('Bir ülkede çalışanların sektörlere dağılımında tarımın payının azalıp hizmetlerin payının artması toplumsal yapı açısından neyi gösterir?', 'Toplumun sanayi ve sanayi sonrası aşamaya doğru dönüştüğünü', ['Toplumun avcı-toplayıcılığa geri döndüğünü', 'Kentleşmenin tamamen durduğunu', 'Ekonomik yapının hiç değişmediğini'], 'Ekonominin ağırlığının tarımdan sanayi ve hizmetlere kayması modernleşme ve kentleşmenin temel göstergesidir.'),
  ('Dinin toplumsal değişmeyle ilişkisi konusunda en dengeli sosyolojik değerlendirme hangisidir?', 'Din, koşullara göre hem süreklilik sağlayabilir hem de değişmeye kaynaklık edebilir', ['Din her durumda değişmeyi engeller', 'Din toplumsal değişmeyle hiçbir şekilde ilişkili değildir', 'Din yalnızca ekonomik değişmenin bir sonucudur'], 'Durkheim dinin bütünleştirici, Weber ise değişmeyi tetikleyebilen yönünü vurgulamıştır; din tarihsel koşullara göre farklı roller üstlenebilir.'),
  ('Karizmatik otoritenin geleneksel ve yasal-ussal otoriteye göre daha istikrarsız olmasının nedeni hangisidir?', 'Liderin kişisine bağlı olması ve kurallara dayanmaması', ['Kuşaklar boyu süren geleneklere dayanması', 'Yazılı yasalarla ve yönetmeliklerle ayrıntılı biçimde düzenlenmesi', 'Makamın kişiden bağımsız olması'], 'Karizmatik otorite liderin olağanüstü niteliklerine duyulan inanca dayanır; lider gidince ya da inanç sarsılınca otorite de zayıflar.'),
  ('İbn Haldun\'un toplumsal yaşamı iklim, coğrafya ve geçim biçimleriyle ilişkilendirmesi onu modern sosyolojinin hangi ilkesine yaklaştırır?', 'Toplumsal olayların gözlenebilir koşullarla açıklanabileceği', ['Toplumsal olayların hiçbir nedene bağlı olmadığı', 'Toplumların yalnızca bireysel iradeyle değiştiği', 'Toplumsal olayların incelenemeyeceği'], 'İbn Haldun, toplumsal farklılıkları doğaüstü açıklamalarla değil, gözlemlenebilir çevresel ve ekonomik koşullarla açıklamaya çalışmıştır.'),
  ('Türk sosyolojisinin ilk dönemlerinde Ziya Gökalp ile Prens Sabahattin arasındaki görüş ayrılığının temel konusu hangisidir?', 'Toplumun mu yoksa bireyin mi esas alınacağı', ['Sosyolojinin bilim olup olmadığı', 'İstatistiğin kullanılıp kullanılmayacağı', 'Köy araştırmalarının yapılıp yapılmayacağı ve nasıl yapılacağı'], 'Gökalp toplumu bireyden üstün tutan Durkheimcı bir çizgide, Prens Sabahattin ise bireysel girişimi öne çıkaran bir çizgideydi.'),
  ('Merton\'un sınıflamasında toplumun amaç ve araçlarını reddedip yerlerine yenilerini koymaya çalışan uyum biçimi hangisidir?', 'Başkaldırı', ['Ritüelcilik', 'Geri çekilme', 'Uyumculuk'], 'Başkaldırıda birey mevcut amaç ve araçları reddeder, bunların yerine yeni bir düzen önerir; devrimci hareketler buna örnektir.'),
  ('Bir şirket birleşmesinde iki farklı şirket kültürünün çalışanlarının zamanla ortak bir çalışma düzeni oluşturması hangi süreçle en iyi açıklanır?', 'Uyum ve bütünleşme', ['Çatışma ve ayrışma', 'Etiketleme ve sapma', 'Kast ve tabakalaşma'], 'Farklı grupların karşılıklı ayarlamalarla ortak bir düzen kurması uyum ve bütünleşme sürecidir.'),
  ('Rol çatışmasının azaltılmasında kullanılabilecek yollardan biri hangisidir?', 'Rolleri önem sırasına koyup zaman ve mekân olarak ayırmak', ['Bütün rolleri aynı anda en yüksek düzeyde yerine getirmeye çalışmak', 'Statü sayısını sürekli artırmak', 'Rollerin beklentilerini hiç dikkate almamak'], 'Bireyler rollerini önceliklendirerek, ayrı zaman ve yerlere bölerek ya da bazı rollerden vazgeçerek rol çatışmasını azaltabilir.'),
  ('Bir toplumda "çalışkanlık" ile "boş zamanın değerli olması" gibi iki değer arasında gerilim yaşanması neyi gösterir?', 'Değerlerin kendi aralarında çatışabileceğini', ['Değerlerin hiçbir zaman birbirini etkilemediğini', 'Toplumda hiç değer bulunmadığını', 'Değerlerin yalnız yasalarla belirlendiğini'], 'Toplumlar birden çok değere sahiptir ve bunlar belirli durumlarda birbiriyle çelişebilir; birey bu durumda aralarında seçim yapmak zorunda kalır.'),
  ('Toplumsal yapının yavaş değiştiği, ama yine de değiştiği yargısını en iyi destekleyen örnek hangisidir?', 'Geniş aileden çekirdek aileye geçişin kuşaklar boyunca yaşanması', ['Bir kişinin bir gün içinde kıyafet değiştirmesi', 'Bir maçta skorun değişmesi', 'Günlük hava durumunun değişmesi'], 'Aile yapısı gibi temel yapı öğeleri bir anda değil, uzun süreçler içinde dönüşür.'),
  ('Bir kentte yoksulluğu azaltmaya yönelik politikaların kalıcı olabilmesi için sosyolojik açıdan hangisi önceliklidir?', 'Eğitim ve istihdam olanaklarına erişimin artırılması', ['Yalnızca bir kerelik yardım dağıtılması', 'Yoksulların kent dışına taşınması', 'Yoksulluğun varlığının resmi olarak reddedilmesi'], 'Eğitim ve iş olanakları yoksulluğun kuşaklar arası aktarımını kırmaya yardımcı olur; tek seferlik yardımlar kalıcı çözüm sağlamaz.'),
  ('Bir toplumda alt kültürlerin çok sayıda bulunmasının olumlu bir sonucu olarak hangisi gösterilebilir?', 'Kültürel çeşitliliğin ve zenginliğin artması', ['Ortak kültürün tamamen yok olması', 'Toplumsal kurumların işlevsizleşmesi ve dağılması', 'Toplumsal etkileşimin durması'], 'Alt kültürler farklı yaşam biçimleri, sanat ve gelenekler aracılığıyla genel kültüre çeşitlilik katar.'),
  ('Bir kişinin aynı anda hem Türk, hem İzmirli, hem öğretmen, hem de bir spor kulübünün taraftarı olarak kendini tanımlaması sosyolojik açıdan neyi gösterir?', 'Kimliklerin çoklu ve katmanlı olabileceğini', ['Kimliğin tek ve değişmez olduğunu', 'Kimliğin yalnızca doğuştan ve kesin olarak belirlendiğini', 'Kişinin hiçbir gruba ait olmadığını'], 'Modern toplumlarda bireyler ulusal, yerel, mesleki ve kültürel gibi farklı düzeylerde birden çok kimliği bir arada taşır.'),
  ('Bir toplumda ekonomik krizin aile içi gerilimleri artırması, okul terkini çoğaltması ve siyasal tercihleri değiştirmesi, toplumsal kurumlar hakkında hangi değerlendirmeyi destekler?', 'Kurumların bir sistem olarak birbirine bağlı olduğunu', ['Kurumların birbirinden tamamen yalıtılmış biçimde işlediğini', 'Ekonominin diğer kurumları hiç etkilemediğini', 'Kurumların yalnız bireysel tercihlere bağlı olduğunu'], 'Bir kurumdaki sarsıntının öteki kurumlara yayılması, toplumsal kurumların karşılıklı bağımlılık içinde işlediğini gösterir.'),
  ('Modern Türkiye\'de çocukların hem anne hem baba tarafındaki akrabalarını akraba sayması hangi akrabalık ilkesine uyar?', 'Çift taraflı (bilateral) akrabalık', ['Yalnızca anasoylu akrabalık', 'Yalnızca babasoylu (patrilineal) akrabalık', 'Manevi akrabalık'], 'Çift taraflı sistemde akrabalık hem anne hem baba tarafından eşit biçimde tanınır; soyadı baba tarafından gelse de akrabalık iki taraflıdır.'),
  ('Bir toplumun avcı-toplayıcılıktan tarıma, tarımdan sanayiye geçişinde en belirleyici etkenin teknoloji olduğunu savunan bir görüş için en uygun kanıt hangisidir?', 'Saban, buhar makinesi gibi araçların üretim biçimini köklü biçimde değiştirmesi', ['Toplumların dil yapılarının hiç değişmemesi', 'Her toplumda aynı bayramların kutlanması', 'Toplum türlerinin hiçbir dönemde değişmemesi'], 'Üretim araçlarındaki büyük yenilikler geçim biçimini, yerleşmeyi ve toplumsal örgütlenmeyi dönüştürmüştür.'),
  ('Sosyolojinin Avrupa\'da 19. yüzyılda ayrı bir bilim olarak doğmasıyla, İbn Haldun\'un 14. yüzyıldaki çalışmaları arasındaki ilişki en doğru nasıl değerlendirilir?', 'İbn Haldun öncü sayılır, ama kurumsal bir bilim olarak sosyoloji 19. yüzyılda oluşmuştur', ['İbn Haldun sosyolojinin adını ilk kez kullanan kişidir', 'İbn Haldun\'un çalışmalarının toplumla hiçbir ilgisi yoktur', 'Sosyoloji 14. yüzyılda üniversitelerde ders olarak okutulmaktaydı'], 'İbn Haldun toplumsal olayları sistemli inceleyen bir öncüdür; ancak sosyoloji adını ve kurumsal kimliğini Comte\'la birlikte 19. yüzyılda kazanmıştır.'),
  ('Kent merkezlerinde aynı köyden ya da bölgeden gelenlerin aynı mahallelere yerleşme eğilimi sosyolojik olarak en çok neyle açıklanır?', 'Göç zincirleri ve hemşehrilik ağlarıyla', ['Kentin iklim koşullarıyla', 'Bireylerin kalıtsal ve bedensel özellikleriyle', 'Kentteki moda akımlarıyla'], 'Önceden göç etmiş akraba ve hemşehriler yeni gelenlere bilgi ve destek sağlar; bu da belirli mahallelerde yoğunlaşmaya yol açar.'),
  ('Sosyal medyada kullanıcılara yalnızca kendi görüşlerine benzer içeriklerin gösterilmesi toplumsal açıdan hangi riski doğurabilir?', 'Farklı görüşlerle karşılaşmanın azalması ve kutuplaşmanın artması', ['Bilgiye erişimin tamamen sona ermesi', 'Bütün toplumun aynı görüşü benimsemesi', 'Toplumsal etkileşimin tamamen durması'], 'Kişiye göre süzülen içerikler, bireyleri benzer düşünenlerle sınırlayan yankı odaları oluşturarak gruplar arası kutuplaşmayı artırabilir.'),
  ('Bir sınıfta öğrencilerin kendi aralarında küçük kliklere ayrılması öğretmen açısından hangi sosyolojik gerçeği hatırlatır?', 'Büyük grupların içinde daha küçük alt grupların oluşabileceğini', ['Sınıfın toplumsal grup sayılamayacağını', 'Öğrenciler arasında hiç etkileşim olmadığını', 'Grupların her zaman tek parça kaldığını'], 'Büyük gruplarda yakınlık, ilgi ve benzerlik temelinde daha küçük alt gruplar oluşur; bu alt gruplar sınıf iklimini etkileyebilir.'),
  ('Bir ülkede yükseköğretime giriş sınavlarında başarılı olan öğrencilerin büyük çoğunluğunun yüksek gelirli ailelerden gelmesi, o toplumdaki hareketlilik hakkında hangi çıkarımı destekler?', 'Fırsat eşitliğinin sınırlı olduğu', ['Toplumun kast sistemine sahip olduğu', 'Eğitimin hiçbir işlev görmediği', 'Yatay hareketliliğin olanaksız olduğu'], 'Başarının aile geliriyle güçlü biçimde ilişkili olması, bireylerin yükselme şansının eşit olmadığını gösterir.'),
  ('"Aile, toplumun en küçük birimidir" sözü sosyolojik olarak en doğru hangi anlamda kabul edilebilir?', 'Toplumsal kurumların temel değerleri ilk olarak aile içinde aktarılır', ['Bütün toplumsal olaylar yalnızca aile içinde yaşanır', 'Aile dışında hiçbir toplumsal grup yoktur', 'Aile her toplumda aynı biçime sahiptir'], 'Aile, bireyin toplumla ilk bağının kurulduğu ve temel değerlerin aktarıldığı kurum olduğu için toplumun temel birimi sayılır.'),
  ('Kentleşme sürecinde aile, komşuluk ve akrabalık bağlarının zayıflamasıyla bireyin yalnızlaşması Durkheim\'ın hangi kavramıyla ilişkilendirilebilir?', 'Anomi', ['Asabiyet', 'Kültürlenme', 'Karizma'], 'Hızlı kentleşmede eski normlar geçerliliğini yitirirken yenileri yerleşmemiş olabilir; bu durum Durkheim\'ın anomi kavramıyla açıklanır.'),
];
